int* prisonAfterNDays(int* cells, int n, int* returnSize) {
    n = (n - 1) % 14 + 1;

    for (int day = 0; day < n; ++day) {
        int next[8] = {0};
        for (int i = 1; i < 7; ++i) {
            next[i] = (cells[i - 1] == cells[i + 1]) ? 1 : 0;
        }
        for (int i = 0; i < 8; ++i) cells[i] = next[i];
    }

    int* result = (int*)malloc(8 * sizeof(int));
    for (int i = 0; i < 8; ++i) result[i] = cells[i];
    *returnSize = 8;
    return result;
}

int main(void) {
    char line[256];
